import{describe,it,expect}from"vitest";import{RIVERS_DATABASE}from"../../frontend/river-origin-challenge/script.js";describe("River Origin Challenge Dataset & Features",()=>{it("should contain 10 major Indian river systems with valid geographical properties",()=>{expect(RIVERS_DATABASE).toHaveLength(10);const e=RIVERS_DATABASE.map(e=>e.id);expect(e).toEqual(expect.arrayContaining(["ganga","yamuna","brahmaputra","godavari","krishna","narmada","kaveri","mahanadi","indus","tapti"])),RIVERS_DATABASE.forEach(e=>{expect(e).toHaveProperty("id"),expect(e).toHaveProperty("name"),expect(e).toHaveProperty("length"),expect(e).toHaveProperty("origin"),expect(e.originCoords).toHaveLength(2),expect(e).toHaveProperty("tributaries"),expect(e.tribCoords).toHaveLength(2),expect(e).toHaveProperty("destination"),expect(e.destCoords).toHaveLength(2),expect(e).toHaveProperty("states"),expect(e).toHaveProperty("educationalExplanation")})}),it("should verify Ganga origin glacier details",()=>{const e=RIVERS_DATABASE.find(e=>"ganga"===e.id);expect(e.origin).toContain("Gangotri Glacier"),expect(e.destination).toContain("Bay of Bengal"),expect(e.tributaries).toContain("Yamuna")}),it("should verify Narmada rift valley origin",()=>{const e=RIVERS_DATABASE.find(e=>"narmada"===e.id);expect(e.origin).toContain("Amarkantak"),expect(e.destination).toContain("Arabian Sea")}),it("should verify Godavari Dakshin Ganga details",()=>{const e=RIVERS_DATABASE.find(e=>"godavari"===e.id);expect(e.origin).toContain("Trimbakeshwar"),expect(e.significance).toContain("Dakshin Ganga")})});